import { expect, test } from "bun:test";
import { realpathSync } from "node:fs";
import { fileURLToPath } from "node:url";
import Ajv from "ajv@^8.17.1";

test("per-command NODE_PATH supplies the real complete graph outside its installation", () => {
  const resolved = realpathSync(fileURLToPath(import.meta.resolve("ajv@^8.17.1")));
  expect(resolved.startsWith("/tmp/scm15-test-deps-rDy0rx/node_modules/ajv/")).toBe(true);
  const validate = new Ajv().compile({ type: "integer", minimum: 1 });
  expect(validate(2)).toBe(true);
  expect(validate("2")).toBe(false);
});
